  const [dcsApprovalRoster, setDcsApprovalRoster] = useState<Array<{ order: number; label: string; role: string; status: "approved" | "pending"; approverUserId?: string; approverRole?: string; decidedAt?: string; assignedUserId?: string }>>([]);
  const [dcsReceipts, setDcsReceipts] = useState<Array<{ userId: string; status: string; readAt: string | null; acknowledgedAt: string | null }>>([]);
  const [dcsGroupCollapsed, setDcsGroupCollapsed] = useState<Record<string, boolean>>({});
  // Review annotations (komentar/highlight gaya Word) untuk versi terpilih.
  type DcsComment = { id: string; authorUserId: string; authorName: string; authorRole: string; anchor: { field?: string; sectionIndex?: number; sectionHeading?: string; quote?: string }; body: string; status: "open" | "resolved"; reviewRound: number; resolvedByName?: string; resolvedAt?: string; createdAt: string };
  const [dcsComments, setDcsComments] = useState<DcsComment[]>([]);
  // Section konten versi terpilih (dari metadata compose) — untuk menautkan
