  const [dcsNumberingRule, setDcsNumberingRule] = useState<{ id: string; tenantId: string; mask: string; scopeTokens: string[]; isOverride: boolean } | null>(null);
  const [dcsNumberingMaskDraft, setDcsNumberingMaskDraft] = useState("");
