  // Sisipkan teks di posisi kursor sebuah textarea (via ref), lalu kembalikan
  // fokus + caret setelah token. Dipakai palet token narasi & klausul.
  const insertAtCursor = (
    ref: React.MutableRefObject<HTMLTextAreaElement | null>,
    currentVal: string,
    insert: string,
    apply: (next: string) => void,
  ) => {
    const ta = ref.current;
    const s = ta?.selectionStart ?? currentVal.length;
    const e = ta?.selectionEnd ?? currentVal.length;
    const next = currentVal.slice(0, s) + insert + currentVal.slice(e);
    apply(next);
    requestAnimationFrame(() => {
      if (!ta) return;
      ta.focus();
      const pos = s + insert.length;
      ta.setSelectionRange(pos, pos);
    });
  };
