  // Auth gate: verify session, then load app data only once authenticated
  useEffect(() => {
    checkAuth();
    // Tautan reset password dari email membawa ?resetToken=... — tangkap di
    // sini lalu bersihkan dari URL supaya tidak tertinggal di riwayat browser.
    const params = new URLSearchParams(window.location.search);
    const tokenFromUrl = params.get("resetToken");
    if (tokenFromUrl) {
      setResetToken(tokenFromUrl);
      setAuthGateMode("reset");
      params.delete("resetToken");
      const rest = params.toString();
      window.history.replaceState({}, "", window.location.pathname + (rest ? `?${rest}` : ""));
    }
    // "Ingat saya" hanya mengingat ALAMAT EMAIL (localStorage) supaya tidak
    // perlu diketik ulang — password mentah TIDAK PERNAH disimpan di
    // localStorage/browser storage manapun oleh kode ini; "ingat password"
    // yang sesungguhnya (kredensial tersimpan aman) diserahkan ke password
    // manager bawaan browser lewat atribut autoComplete pada input di bawah.
    const rememberedEmail = window.localStorage.getItem("clm_remembered_email");
    if (rememberedEmail) {
      setLoginForm((f) => ({ ...f, email: rememberedEmail }));
      setRememberMe(true);
    }
  }, []);

  // Daftarkan Service Worker untuk Push Notification
  useEffect(() => {
    if ("serviceWorker" in navigator && "PushManager" in window) {
      setPushSupported(true);
      navigator.serviceWorker.register("/sw.js").then((reg) => {
        setSwRegistration(reg);
        // Cek apakah sudah subscribe
        reg.pushManager.getSubscription().then((sub) => {
          setPushSubscribed(!!sub);
        });
      }).catch((err) => console.warn("SW registration failed:", err));

      // Dengarkan pesan dari SW (NOTIFICATION_CLICK)
      navigator.serviceWorker.addEventListener("message", (event) => {
        if (event.data?.type === "NOTIFICATION_CLICK") {
          const url = event.data.url || "/";
          if (url.includes("contract=")) {
            const id = new URLSearchParams(url.split("?")[1]).get("contract");
            if (id) {
              const c = contracts.find((x) => x.id === id);
              if (c) { setSelectedContract(c); setActiveTab("monitoring"); }
            }
          } else if (url.includes("dcsDocument=")) {
            const id = new URLSearchParams(url.split("?")[1]).get("dcsDocument");
            if (id) {
              const d = dcsDocs.find((x) => x.id === id);
              if (d) { setActiveTab("internal-docs"); setDcsSelectedId(d.id); setDcsSelectedVersionId(d.versions[0]?.id || null); }
            }
          }
        }
      });
    }
  }, []);

  // Global 401 guard: if the session expires mid-use (any of the app's many
  // fetch() calls gets a 401), drop back to the login screen instead of
  // leaving the UI in a half-broken state with silently failing requests.
  useEffect(() => {
    const originalFetch = window.fetch;
    window.fetch = async (...args) => {
      const res = await originalFetch(...args);
      const url = typeof args[0] === "string" ? args[0] : (args[0] as Request).url;
      if (res.status === 401 && !url.includes("/api/auth/")) {
        setCurrentUser(null);
        setCurrentTenant(null);
      }
      return res;
    };
    return () => {
      window.fetch = originalFetch;
    };
  }, []);

