  // Uploads the company logo and merges the result into the (not-yet-saved)
  // appSettings state — persisted for real via the existing "Simpan
  // Konfigurasi" button / PUT /api/settings call, no separate save action.
  const handleUploadCompanyLogo = async (file: File) => {
    setIsUploadingLogo(true);
    try {
      const fd = new FormData();
      fd.append("file", file);
      const res = await fetch("/api/settings/company-logo", { method: "POST", body: fd });
      const data = await res.json();
      if (data.url) {
        setAppSettings({ ...appSettings, companyLogoUrl: data.url, companyLogoKey: data.key, companyLogoMimeType: data.mimeType });
        showToast("Logo terunggah — klik 'Simpan Konfigurasi' untuk menyimpannya", "success");
      } else showToast(data.error || "Gagal mengunggah logo", "warning");
    } catch { showToast("Gagal mengunggah logo", "warning"); }
    finally { setIsUploadingLogo(false); }
  };

  const handleAddFolder = async (name: string) => {
    if (!name.trim()) return;
    const res = await fetch("/api/clause-categories", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ category: name.trim() }),
    });
    const data = await res.json();
    if (data.categories) setClauseCategories(data.categories);
    showToast(`Folder "${name}" ditambahkan`, "success");
  };

  // Sub-folder tree (dipakai di Arsip Dokumen drill-down & picker Create Kontrak)
  const handleAddSubFolder = async (category: string, parentId: string | null, name: string) => {
    if (!name.trim()) return;
    try {
      const res = await fetch("/api/subfolders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ category, parentId, name: name.trim() }),
      });
      const data = await res.json();
      if (!res.ok) { showToast(data.error || "Gagal membuat sub folder", "warning"); return; }
      setSubFolders((prev) => [...prev, data]);
      showToast(`Sub folder "${name}" dibuat`, "success");
    } catch {
      showToast("Gagal membuat sub folder", "warning");
    }
  };

  const handleRenameSubFolder = async (id: string, name: string) => {
    if (!name.trim()) return;
    try {
      const res = await fetch(`/api/subfolders/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: name.trim() }),
      });
      const data = await res.json();
      if (!res.ok) { showToast(data.error || "Gagal mengubah nama folder", "warning"); return; }
      setSubFolders((prev) => prev.map((f) => (f.id === id ? data : f)));
      showToast("Nama folder diperbarui", "success");
    } catch {
      showToast("Gagal mengubah nama folder", "warning");
    }
  };

